import{d as l,C as r,o as h,c as u,j as i,a as e,E as a,a3 as m}from"./chunks/framework.Q4yG9rk_.js";const c=JSON.parse('{"title":"中庸·第26章","description":"《中庸》第 26 章——至诚无息：不息则久久则征，徵则悠远博厚高明；博厚配地、高明配天、悠久无疆；其为物不贰，则其生物不测；纯亦不已。","frontmatter":{"title":"中庸·第26章","description":"《中庸》第 26 章——至诚无息：不息则久久则征，徵则悠远博厚高明；博厚配地、高明配天、悠久无疆；其为物不贰，则其生物不测；纯亦不已。","category":"guide","aliases":["第26章","中庸第26章","至诚无息"],"source":["《礼记》","《四书章句集注》"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/sishu-wujing/zhongyong/chapter-26.md","filePath":"lizhimingde/sishu-wujing/zhongyong/chapter-26.md","lastUpdated":1790316338000}'),d={name:"lizhimingde/sishu-wujing/zhongyong/chapter-26.md"},w=l({...d,setup(y){const o=[{id:"wuxi",label:"至诚无息 · 不息则久，久则征",showLabel:!0,sentences:[["故至诚",{text:"无息",glossary:"wuxi"},"。不息则",{text:"久",glossary:"jiu"},"，久则",{text:"征",glossary:"zheng"},"，征则",{text:"悠远",glossary:"youyuan"},"，悠远则",{text:"博厚",glossary:"bohou"},"，博厚则",{text:"高明",glossary:"gaoming"},"。"]],note:"「故至诚无息」——至诚之德，永不停息。「不息则久」：不停息便能长久；「久则征」（征＝验于外），「征则悠远，悠远则博厚，博厚则高明」——一层推一层，写至诚之德由内而外、由近及远的展开。"},{id:"peitiandi",label:"博厚所以载物 · 配地配天 · 悠久无疆",showLabel:!0,sentences:[["博厚，所以",{text:"载物",glossary:"zaiwu"},"也；高明，所以",{text:"覆物",glossary:"fuwu"},"也；悠久，所以成物也。博厚配地，高明配天，悠久",{text:"无疆",glossary:"wujiang"},"。"]],note:"「博厚，所以载物也；高明，所以覆物也；悠久，所以成物也」——博厚用来承载万物，高明用来覆盖万物，悠久用来成就万物。再配以天地：「博厚配地，高明配天，悠久无疆。」"},{id:"wuxiwei",label:"不见而章 · 不动而变 · 无为而成",showLabel:!0,sentences:[["如此者，",{text:"不见而章",glossary:"buxianzhang"},"，",{text:"不动而变",glossary:"budongbian"},"，",{text:"无为而成",glossary:"wuwei"},"。"],["天地之道，可一言而尽也：其为物",{text:"不贰",glossary:"buer"},"，则其生物",{text:"不测",glossary:"buce"},"。"]],note:"「如此者，不见而章，不动而变，无为而成」——不待显露而自彰著，不去推动而自变化，不作妄为而自成功。又：「天地之道，可一言而尽也：其为物不贰，则其生物不测」——天地之道一言可尽：其为物纯一不二，故其生物不可测度。"},{id:"tiandi",label:"天地之道：博厚高明悠久 · 天昭昭之多，地一撮土之多",showLabel:!0,sentences:[["天地之道：博也，厚也，高也，明也，悠也，久也。"],["今夫天，斯",{text:"昭昭",glossary:"zhaozhao"},"之多，及其无穷也，日月星辰系焉，万物覆焉。今夫地，一撮土之多，及其广厚，载华岳而不重，振河海而不泄，万物载焉。"]],note:"「天地之道：博也，厚也，高也，明也，悠也，久也」——天地之道，尽于这六字。以下用「积少成多」设喻：「今夫天，斯昭昭之多」，推到无穷，则「日月星辰系焉，万物覆焉」；「今夫地，一撮土之多」，推到广厚，则「载华岳而不重，振河海而不泄，万物载焉」。"},{id:"shanshui",label:"山一卷石 · 水一勺 · 及其广大不测",showLabel:!0,sentences:[["今夫山，一",{text:"卷石",glossary:"quanshi"},"之多，及其广大，草木生之，禽兽居之，宝藏兴焉。今夫水，一",{text:"勺",glossary:"shao"},"之多，及其不测，鼋鼍、蛟龙、鱼鳖生焉，货财殖焉。"]],note:"再以山水为喻：「今夫山，一卷石之多」（卷＝拳，拳头大的石头），及其广大，则「草木生之，禽兽居之，宝藏兴焉」；「今夫水，一勺之多」，及其不测，则「鼋鼍、蛟龙、鱼鳖生焉，货财殖焉」。皆言由微而著之理。"},{id:"buji",label:"维天之命，於穆不已 · 文王之德之纯",showLabel:!0,sentences:[["《诗》云：“维天之命，",{text:"於穆不已",glossary:"yumubuyi"},"！”盖曰天之所以为天也。“於乎不显！文王之德之纯！”盖曰文王之所以为文也，",{text:"纯亦不已",glossary:"chunyibuyi"},"。"]],note:"引《诗》「维天之命，於穆不已」——天命深远而不止息，这是说「天之所以为天」。又引「於乎不显！文王之德之纯」——何等光明！文王之德那样纯粹；这是说「文王之所以为文」——「纯亦不已」，纯一而不止息。全章以「不已」收束。"}],s=[{id:"wuxi",term:"无息",pinyin:"wú xī",meaning:"朱注：「既无虚假，自无间断。」不息，即不间断。"},{id:"jiu",term:"久",pinyin:"jiǔ",meaning:"朱注：「久，常于中也。」"},{id:"zheng",term:"征",pinyin:"zhēng",meaning:"朱注：「征，验于外也。」"},{id:"youyuan",term:"悠远",pinyin:"yōu yuǎn",meaning:"悠长而遥远。朱注：「存诸中者既久，则验于外者益悠远而无究矣。」"},{id:"bohou",term:"博厚",pinyin:"bó hòu",meaning:"广博而深厚。"},{id:"gaoming",term:"高明",pinyin:"gāo míng",meaning:"高大而光明。"},{id:"zaiwu",term:"载物",pinyin:"zài wù",meaning:"承载万物（地之德）。"},{id:"fuwu",term:"覆物",pinyin:"fù wù",meaning:"覆盖万物（天之德）。"},{id:"wujiang",term:"无疆",pinyin:"wú jiāng",meaning:"无边际。朱注：「此言圣人与天地同体。」"},{id:"buxianzhang",term:"不见而章",pinyin:"bù xiàn ér zhāng",meaning:"见：读 xiàn（显现）；章：同「彰」。不待显现而自然昭彰。"},{id:"budongbian",term:"不动而变",pinyin:"bù dòng ér biàn",meaning:"不须动作而变化自行。"},{id:"wuwei",term:"无为而成",pinyin:"wú wéi ér chéng",meaning:"不刻意作为而事成。"},{id:"buer",term:"不贰",pinyin:"bù èr",meaning:"不二、纯一。朱注：「不贰，所以诚也。」"},{id:"buce",term:"不测",pinyin:"bù cè",meaning:"不可测度。诚一故不息，生物之多莫知其所以然。"},{id:"zhaozhao",term:"昭昭",pinyin:"zhāo zhāo",meaning:"犹耿耿，一点小光明。朱注：「此指其一处而言之。」"},{id:"quanshi",term:"卷石",pinyin:"quán shí",meaning:"卷：读 quán，同「区」，一区之石。"},{id:"shao",term:"一勺",pinyin:"yī sháo",meaning:"一勺之水。"},{id:"yumubuyi",term:"於穆不已",pinyin:"wū mù bù yǐ",meaning:"《诗·周颂·维天之命》。於：叹辞，读 wū；穆：深远；不已：不间断。"},{id:"chunyibuyi",term:"纯亦不已",pinyin:"chún yì bù yǐ",meaning:"纯：纯一不杂。文王之德既纯且不间断。程子：「纯则无二无杂，不已则无间断先后。」"}];return(p,n)=>{const g=r("DaoTextReading"),t=r("DaoKeywordCards");return h(),u("div",null,[n[0]||(n[0]=i("h1",{id:"中庸·第26章",tabindex:"-1"},[e("中庸·第26章 "),i("a",{class:"header-anchor",href:"#中庸·第26章","aria-label":'Permalink to "中庸·第26章"'},"​")],-1)),n[1]||(n[1]=i("h2",{id:"【原典层】原文",tabindex:"-1"},[e("【原典层】原文 "),i("a",{class:"header-anchor",href:"#【原典层】原文","aria-label":'Permalink to "【原典层】原文"'},"​")],-1)),n[2]||(n[2]=i("p",null,"第二十六章以「至诚无息」起头，一路推到「博厚配地、高明配天、悠久无疆」，再以天地、山川、一撮土、一勺水作喻，收在《诗》的「纯亦不已」。默认竹简沉浸通读；切「经典阅读」可点生词。",-1)),a(g,{colophon:"至诚无息 · 博厚高明悠久 · 纯亦不已",tone:"ink",sections:o,glossary:s,"default-mode":"slips","aria-label":"中庸·第26章 原文"}),n[3]||(n[3]=i("h2",{id:"【原典层】注音与字词",tabindex:"-1"},[e("【原典层】注音与字词 "),i("a",{class:"header-anchor",href:"#【原典层】注音与字词","aria-label":'Permalink to "【原典层】注音与字词"'},"​")],-1)),a(t,{items:[{term:"无息",pinyin:["wú","xī"],meaning:"朱注：「既无虚假，自无间断。」不是用力不停，而是不假故不断。"},{term:"久",pinyin:["jiǔ"],meaning:"常于中。"},{term:"征",pinyin:["zhēng"],meaning:"验于外。"},{term:"悠远",pinyin:["yōu","yuǎn"],meaning:"中既久，则外益远。"},{term:"博厚",pinyin:["bó","hòu"],meaning:"配地，所以载物。"},{term:"高明",pinyin:["gāo","míng"],meaning:"配天，所以覆物。"},{term:"悠久",pinyin:["yōu","jiǔ"],meaning:"无疆，所以成物。"},{term:"不见而章",pinyin:["bù","xiàn","ér","zhāng"],meaning:"见读 xiàn，章同「彰」——不待显现而自然昭彰。"},{term:"不动而变",pinyin:["bù","dòng","ér","biàn"],meaning:"不须动作而变化自成。"},{term:"无为而成",pinyin:["wú","wéi","ér","chéng"],meaning:"不刻意作为而事成。"}]}),a(t,{items:[{term:"其为物不贰",pinyin:["qí","wéi","wù","bù","èr"],meaning:"不贰：不二、纯一。朱注：「不贰，所以诚也。」"},{term:"其生物不测",pinyin:["qí","shēng","wù","bù","cè"],meaning:"生成万物而不可测度。朱注：「诚故不息，而生物之多，有莫知其所以然者。」"},{term:"昭昭之多",pinyin:["zhāo","zhāo","zhī","duō"],meaning:"一点小光明。朱注：「此指其一处而言之。」"},{term:"一撮土",pinyin:["yī","cuō","tǔ"],meaning:"一把土。"},{term:"一卷石",pinyin:["yī","quán","shí"],meaning:"卷：读 quán，同「区」。一区之石。"},{term:"一勺",pinyin:["yī","sháo"],meaning:"一勺之水。朱注提醒「不以辞害意」——非谓天地山川实由积累而后大。"},{term:"於穆不已",pinyin:["wū","mù","bù","yǐ"],meaning:"《诗》句。於读 wū（叹辞），穆：深远——天之所以为天。"},{term:"纯亦不已",pinyin:["chún","yì","bù","yǐ"],meaning:"纯：纯一不杂——文王之所以为文。程子：「纯则无二无杂，不已则无间断先后。」"}]}),n[4]||(n[4]=m("",29))])}}});export{c as __pageData,w as default};
